#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>

struct ClientRecord {
    unsigned int account;
    std::string name;
    double balance;
};

int main() {
    // Simulate sequential text file contents ("clients.txt")
    std::string fileData =
        "100 Jones 24.98\n"
        "200 Doe 345.67\n"
        "300 White 0.00\n"
        "400 Stone -42.16\n"
        "500 Rich 224.62\n";

    std::istringstream stream(fileData);

    // Pass 1: Read and display all records
    std::cout << std::left << std::setw(10) << "Account"
              << std::setw(13) << "Name"
              << std::right << std::setw(7) << "Balance" << "\n";

    ClientRecord rec;
    while (stream >> rec.account >> rec.name >> rec.balance) {
        std::cout << std::left << std::setw(10) << rec.account
                  << std::setw(13) << rec.name
                  << std::right << std::fixed << std::setprecision(2)
                  << std::setw(7) << rec.balance << "\n";
    }

    // Reset stream back to start (equivalent to rewind())
    stream.clear();
    stream.seekg(0, std::ios::beg);

    // Pass 2: Print only negative balances
    std::cout << "\nAccounts with negative balances:\n";
    while (stream >> rec.account >> rec.name >> rec.balance) {
        if (rec.balance < 0.0) {
            std::cout << std::left << std::setw(10) << rec.account
                      << std::setw(13) << rec.name
                      << std::right << std::fixed << std::setprecision(2)
                      << std::setw(7) << rec.balance << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <iomanip>

struct Account {
    unsigned int id;
    std::string name;
    double balance;
};

void runInquiry(const std::string& fileData, const std::vector<int>& requests) {
    std::istringstream stream(fileData);

    for (int req : requests) {
        std::cout << "Enter request: " << req << "\n";
        if (req == 4) {
            std::cout << "End of run.";
            break;
        }

        Account acc;
        switch (req) {
            case 1:
                std::cout << "\nAccounts with zero balances:\n";
                while (stream >> acc.id >> acc.name >> acc.balance) {
                    if (acc.balance == 0.0) {
                        std::cout << std::left << std::setw(10) << acc.id
                                  << std::setw(15) << acc.name
                                  << std::right << std::fixed << std::setprecision(2)
                                  << std::setw(6) << acc.balance << "\n";
                    }
                }
                break;
            case 2:
                std::cout << "\nAccounts with credit balances:\n";
                while (stream >> acc.id >> acc.name >> acc.balance) {
                    if (acc.balance < 0.0) {
                        std::cout << std::left << std::setw(10) << acc.id
                                  << std::setw(13) << acc.name
                                  << std::right << std::fixed << std::setprecision(2)
                                  << std::setw(8) << acc.balance << "\n";
                    }
                }
                break;
            case 3:
                std::cout << "\nAccounts with debit balances:\n";
                while (stream >> acc.id >> acc.name >> acc.balance) {
                    if (acc.balance > 0.0) {
                        std::cout << std::left << std::setw(10) << acc.id
                                  << std::setw(14) << acc.name
                                  << std::right << std::fixed << std::setprecision(2)
                                  << std::setw(7) << acc.balance << "\n";
                    }
                }
                break;
            default:
                break;
        }

        // Reset stream state and offset for next pass (rewind)
        stream.clear();
        stream.seekg(0, std::ios::beg);
        std::cout << "\n";
    }
}

int main() {
    std::string clientsData =
        "100 Jones 24.98\n"
        "200 Doe 345.67\n"
        "300 White 0.00\n"
        "400 Stone -42.16\n"
        "500 Rich 224.62\n";

    std::vector<int> menuInputs = {1, 2, 3, 4};
    runInquiry(clientsData, menuInputs);
    return 0;
}
